<script setup lang="ts">
import {computed} from 'vue'
import {MapPin,Bell,Users,Pencil} from 'lucide-vue-next'
import type {WorkspaceRecord} from '@nextspace/contracts'
const props=defineProps<{record:WorkspaceRecord;canEdit:boolean;canRespond:boolean;editReason?:string;responseReason?:string;busy?:boolean}>()
const emit=defineEmits<{edit:[];respond:[participation:'ACCEPTED'|'TENTATIVE'|'DECLINED']}>()
const own=computed(()=>props.record.eventScheduling?.attendees.find(item=>item.uri.toLowerCase()===props.record.eventScheduling?.ownAttendeeUri?.toLowerCase()))
function reminder(minutes:number){return minutes===0?'At start':minutes%1440===0?`${minutes/1440} days before`:minutes%60===0?`${minutes/60} hours before`:`${minutes} minutes before`}
</script>
<template><section class="inspector-section event-summary" aria-label="Event details"><header><h3>Event details</h3><button class="text-button" :disabled="!canEdit||busy" @click="emit('edit')"><Pencil :size="14"/>Edit event</button></header><dl><div><dt><MapPin :size="15"/>Location</dt><dd>{{record.location||'Not set'}}</dd></div><div><dt><Bell :size="15"/>Reminders</dt><dd><span v-for="minutes in record.reminders||[]" :key="minutes" class="event-reminder-label">{{reminder(minutes)}}</span><span v-if="!record.reminders?.length">No simple reminders</span><small v-if="record.unsupportedReminderCount">{{record.unsupportedReminderCount}} other native reminders are preserved.</small></dd></div></dl><p v-if="!canEdit&&editReason" class="field-hint">{{editReason}}</p><div v-if="record.eventScheduling?.organizer||record.eventScheduling?.attendees.length" class="event-participants"><h4><Users :size="15"/>Participants</h4><p v-if="record.eventScheduling.organizer" class="event-organizer"><span>Organizer</span><strong>{{record.eventScheduling.organizer.name||record.eventScheduling.organizer.uri}}</strong><small v-if="record.eventScheduling.organizer.name">{{record.eventScheduling.organizer.uri}}</small></p><div v-for="(person,index) in record.eventScheduling.attendees" :key="person.uri+index" class="event-participant"><strong>{{person.name||person.uri}}</strong><small v-if="person.name">{{person.uri}}</small><span>{{person.participation}}<template v-if="person.uri===record.eventScheduling.ownAttendeeUri"> · You</template></span><small v-if="person.scheduleStatus">Native scheduling status: {{person.scheduleStatus}}</small></div><div v-if="record.eventScheduling.role==='attendee'" class="event-response"><strong>Your response: {{own?.participation||'Not recorded'}}</strong><div><button v-for="option in [{value:'ACCEPTED' as const,label:'Accept'},{value:'TENTATIVE' as const,label:'Tentative'},{value:'DECLINED' as const,label:'Decline'}]" :key="option.value" type="button" class="button quiet" :disabled="busy||!canRespond||own?.participation===option.value" @click="emit('respond',option.value)">{{option.label}}</button></div><p v-if="!canRespond&&responseReason" class="field-hint">{{responseReason}}</p></div></div></section></template>
<style scoped>.event-summary dl{margin:0;display:grid;gap:12px}.event-summary dl>div{display:grid;grid-template-columns:100px minmax(0,1fr);gap:10px;font-size:13px}.event-summary dt{display:flex;gap:5px;color:var(--muted);align-items:center}.event-summary dd{margin:0;overflow-wrap:anywhere}.event-summary dd small{display:block;color:var(--muted);margin-top:5px}.event-reminder-label{display:block;margin-bottom:3px}.event-participants{margin-top:16px}.event-participants h4{display:flex;gap:6px;align-items:center;font-size:13px}.event-organizer,.event-participant{display:grid;gap:4px;font-size:13px;margin-top:10px;overflow-wrap:anywhere}.event-organizer>span,.event-participant>span,.event-participants small{font-size:11px;color:var(--muted)}.event-response{margin-top:14px;font-size:12px}.event-response>div{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.event-response .button{min-height:38px}</style>
